fn gcd_calc(m: u32, n: u32) -> u32 {
    debug_assert!(m > 0 && n > 0);

    // Euclidean algorithm.
    // Invariant: gcd(a, b) == gcd(m, n)
    // Positivity: a > 0 and b > 0 throughout the loop
    // Termination: b strictly decreases each iteration (b becomes a % b, which is < b)
    let mut a = m;
    let mut b = n;

    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }

    // With m,n > 0, the gcd is positive.
    a
}